 const learn=(government,economy,society)=>({learning:{government,economy,society}});
 const ph=(a,b,t,x,s,extra={})=>phase(a,b,t,x,Array.isArray(s)?s:[s],extra);
 // Each row carries its own geometry; a previous phase is never extended automatically.
 const add=(id,name,coord,src,color,rows,kind='state')=>{
  entry(id,'eurasia',kind,coord,name,rows.map(r=>ph(r[0],r[1],r[2],r[3],src,r[5]||{})));
  rows.forEach(r=>area(id,r[0],r[1],r[4],{kind:r[6]||'polity',color,sources:Array.isArray(src)?src:[src]}));
 };
 const more=(id,src,color,rows)=>{
  continueEntry(id,rows.map(r=>ph(r[0],r[1],r[2],r[3],src,r[5]||{})));
  rows.forEach(r=>area(id,r[0],r[1],r[4],{kind:r[6]||'polity',color,sources:Array.isArray(src)?src:[src]}));
 };

