 add('late-transoxiana',L('Мавераннахр · власть эмиров','Transoxiana · rule of the amirs','Мавераннахр · эмирлердин бийлиги'),[66.96,39.65],'lateChagatai','#9d9b71',[[1347,1370,L('Западная часть улуса','Western part of the ulus','Улустун батыш бөлүгү'),L('В Мавераннахре реальная власть переходит к эмирам. Из этой борьбы возвышается Тимур.','Amirs hold effective power in Transoxiana. Timur rises from their rivalry.','Мавераннахрда чыныгы бийлик эмирлерге өтөт. Ушул күрөштөн Тимур көтөрүлөт.'),transox]]);
 add('late-moghulistan',L('Могулистан','Moghulistan','Моголстан'),[80.45,43.84],'lateChagatai','#83946d',[[1347,1454,L('Восточное Чагатайское ханство','Eastern Chagatai khanate','Чыгыш Чагатай хандыгы'),L('Туглук-Тимур возглавляет восточную часть улуса. Ханы и эмиры Дуглатов соперничают за Семиречье и оазисы Кашгарии.','Tughluq Timur leads the eastern ulus. Khans and Dughlat amirs compete over Semirechye and the Kashgarian oases.','Тоглук-Тимур улустун чыгышын жетектейт. Хандар менен Дуглат эмирлери Жети-Суу жана Кашкар оазистери үчүн атаандашат.'),eastChag,learn(L('Ханы Чагатаиды и влиятельные эмиры.','Chagatai khans and influential amirs.','Чагатай хандары жана таасирдүү эмирлер.'),L('Пастбища связаны с городскими оазисами.','Pasturelands connect with urban oases.','Жайыттар шаардык оазистер менен байланышат.'),L('Название государства не означает единую этническую группу.','The state’s name does not denote a single ethnic group.','Мамлекеттин аталышы бир гана этносту билдирбейт.'))]]);
